export const validateRegistrySchemaV431 = async () => {
  if (!supabaseClient) initSupabase();
  const discrepancies: string[] = [];

  // Verify basic table accessibility for standard operations
  const { error: accessErr } = await supabaseClient.from('clients').select('id').limit(1);
  if (accessErr) {
    discrepancies.push(`Registry Access Fault: ${accessErr.message}`);
  }

  const { error: logsErr } = await supabaseClient.from('system_logs').select('id').limit(1);
  if (logsErr && (logsErr.code === '42P01' || logsErr.message.includes('schema cache'))) {
    const { error: fallbackErr } = await supabaseClient.from('ingestion_logs').select('id').limit(1);
    if (!fallbackErr) return { success: true, discrepancies: ["Governance Warning: Using 'ingestion_logs' for audit redundancy."] };
    discrepancies.push("Registry Critical: Audit tables missing from cloud schema.");
  }
  return { success: discrepancies.length === 0, discrepancies };
};

