const RETRIEVAL_NOISE = [
  'CO', 'LTD', 'CORP', 'INC', 'INTERNATIONAL', 'LIMITED', 'GROUP', 'COMPANY', 'LLC', 
  'PVT', 'FZE', 'PLC', 'SERVICES', 'TRADING', 'HOLDINGS', 'TRUST', 'SDN', 'BHD', 'BERHAD', 'PRIVATE'
