                    </div>
                  </div>
                  <div className={`px-6 py-3 rounded-2xl flex items-center gap-3 border ${securityDiscrepancies.length === 0 ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-red-50 border-red-100 text-red-800 animate-pulse'}`}>
