                  </div>
                  <div className="bg-amber-50 border border-amber-100 p-6 rounded-2xl flex gap-4 text-amber-800">
                     <Info className="shrink-0" size={20}/>
                     <p className="text-[10px] font-bold leading-relaxed uppercase">
