DROP POLICY IF EXISTS "Clients: authenticated manage" ON "public"."clients";
CREATE POLICY "Clients: authenticated manage" ON "public"."clients" FOR ALL TO authenticated USING (true);

-- 6. Define System Logs (Insert Only for Tracking)
DROP POLICY IF EXISTS "Logs: authenticated append" ON "public"."system_logs";
CREATE POLICY "Logs: authenticated append" ON "public"."system_logs" FOR INSERT TO authenticated WITH CHECK (true);

-- 7. Index Optimization
CREATE INDEX IF NOT EXISTS idx_profiles_user_id ON "public"."profiles"(id);
CREATE INDEX IF NOT EXISTS idx_system_logs_timestamp ON "public"."system_logs"(timestamp DESC);
