-- 0. Enable required extensions
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 1. Create Core Tables if they don't exist
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT UNIQUE NOT NULL,
    full_name TEXT,
    role TEXT,
    is_system_admin BOOLEAN DEFAULT false,
    status TEXT DEFAULT 'Active',
    must_change_password BOOLEAN DEFAULT true,
    password_expiry TIMESTAMPTZ,
    password_hash_mock TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.system_logs (
    id TEXT PRIMARY KEY,
    timestamp TIMESTAMPTZ DEFAULT now(),
    source TEXT,
    method TEXT,
    status TEXT,
    details TEXT,
    triggered_by TEXT
);

CREATE TABLE IF NOT EXISTS public.system_metadata (
    key TEXT PRIMARY KEY,
    value JSONB
);

-- 2. Enable Row Level Security (RLS) on all core tables
ALTER TABLE "public"."profiles" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."clients" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."sanctions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."system_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."ingestion_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."system_metadata" ENABLE ROW LEVEL SECURITY;

-- 3. Define User Profile Access Policies (Self-Management)
-- Note: Fixed UUID vs TEXT mismatch with explicit casting
DROP POLICY IF EXISTS "Profiles: select own" ON "public"."profiles";
CREATE POLICY "Profiles: select own" ON "public"."profiles" 
FOR SELECT TO authenticated 
USING (auth.uid() = id);

-- 4. Define Global Registry Access (Read-Only for Search)
DROP POLICY IF EXISTS "Registry: public read access" ON "public"."sanctions";
CREATE POLICY "Registry: public read access" ON "public"."sanctions" 
FOR SELECT TO public 
USING (true);

-- 5. Define Client Management (Authenticated Access)
DROP POLICY IF EXISTS "Clients: authenticated manage" ON "public"."clients";
CREATE POLICY "Clients: authenticated manage" ON "public"."clients" 
FOR ALL TO authenticated 
USING (true);

-- 6. Define System Logs (Insert Only for Tracking)
DROP POLICY IF EXISTS "Logs: authenticated append" ON "public"."system_logs";
CREATE POLICY "Logs: authenticated append" ON "public"."system_logs" 
FOR INSERT TO authenticated 
WITH CHECK (true);

-- 7. Define Metadata Access (Public Read, No Write)
-- This allows the system to check sync status but prevents unauthorized tamper
DROP POLICY IF EXISTS "Metadata: public read" ON "public"."system_metadata";
CREATE POLICY "Metadata: public read" ON "public"."system_metadata" 
FOR SELECT TO public 
