-- 8. Index Optimization
CREATE INDEX IF NOT EXISTS idx_profiles_user_id ON "public"."profiles"(id);
CREATE INDEX IF NOT EXISTS idx_system_logs_timestamp ON "public"."system_logs"(timestamp DESC);
`;

