    id TEXT PRIMARY KEY,
    timestamp TIMESTAMPTZ DEFAULT now(),
    source TEXT,
    method TEXT,
    status TEXT,
    details TEXT
);

CREATE TABLE IF NOT EXISTS public.system_metadata (
    key TEXT PRIMARY KEY,
    value JSONB
);

-- 2. Schema Hardening: Ensure ownership columns exist on ALL potentially pre-existing tables
ALTER TABLE "public"."audit_logs" ADD COLUMN IF NOT EXISTS "actor_id" TEXT;
ALTER TABLE "public"."auth_logs" ADD COLUMN IF NOT EXISTS "user_id" TEXT;
ALTER TABLE "public"."kyc_workflow_history" ADD COLUMN IF NOT EXISTS "changed_by" TEXT;
ALTER TABLE "public"."system_logs" ADD COLUMN IF NOT EXISTS "triggered_by" TEXT;

-- 3. Enable Row Level Security (RLS)
ALTER TABLE "public"."profiles" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."clients" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."sanctions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."system_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."ingestion_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."system_metadata" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."roles" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."audit_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."auth_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "public"."kyc_workflow_history" ENABLE ROW LEVEL SECURITY;

-- 4. Identity & Profile Access
DROP POLICY IF EXISTS "Profiles: select own" ON "public"."profiles";
CREATE POLICY "Profiles: select own" ON "public"."profiles" FOR SELECT TO authenticated USING (auth.uid()::text = id);

-- 5. Roles (Authenticated Read)
DROP POLICY IF EXISTS "Roles: authenticated read" ON "public"."roles";
CREATE POLICY "Roles: authenticated read" ON "public"."roles" FOR SELECT TO authenticated USING (true);

-- 6. Audit & Auth Logs (Strict Ownership Append)
DROP POLICY IF EXISTS "Logs: authenticated append" ON "public"."audit_logs";
CREATE POLICY "Logs: authenticated append" ON "public"."audit_logs" FOR INSERT TO authenticated WITH CHECK (auth.uid()::text = actor_id);

DROP POLICY IF EXISTS "AuthLogs: authenticated append" ON "public"."auth_logs";
CREATE POLICY "AuthLogs: authenticated append" ON "public"."auth_logs" FOR INSERT TO authenticated WITH CHECK (auth.uid()::text = user_id);

-- 7. KYC Workflow History
DROP POLICY IF EXISTS "Workflow: authenticated append" ON "public"."kyc_workflow_history";
CREATE POLICY "Workflow: authenticated append" ON "public"."kyc_workflow_history" FOR INSERT TO authenticated WITH CHECK (auth.uid()::text = changed_by);

DROP POLICY IF EXISTS "Workflow: authenticated select" ON "public"."kyc_workflow_history";
CREATE POLICY "Workflow: authenticated select" ON "public"."kyc_workflow_history" FOR SELECT TO authenticated USING (true);

-- 8. Standard Registry Access
DROP POLICY IF EXISTS "Registry: public read access" ON "public"."sanctions";
CREATE POLICY "Registry: public read access" ON "public"."sanctions" FOR SELECT TO public USING (true);

DROP POLICY IF EXISTS "Clients: authenticated manage" ON "public"."clients";
CREATE POLICY "Clients: authenticated manage" ON "public"."clients" FOR ALL TO authenticated USING (true);

-- 9. System Logs (Append Check)
DROP POLICY IF EXISTS "SystemLogs: authenticated append" ON "public"."system_logs";
CREATE POLICY "SystemLogs: authenticated append" ON "public"."system_logs" FOR INSERT TO authenticated WITH CHECK (auth.uid()::text = triggered_by);

-- 10. Metadata Read Access
DROP POLICY IF EXISTS "Metadata: public read" ON "public"."system_metadata";
CREATE POLICY "Metadata: public read" ON "public"."system_metadata" FOR SELECT TO public USING (true);

-- 11. Performance Optimization
CREATE INDEX IF NOT EXISTS idx_profiles_email ON "public"."profiles"(email);
CREATE INDEX IF NOT EXISTS idx_audit_logs_actor ON "public"."audit_logs"(actor_id);
CREATE INDEX IF NOT EXISTS idx_workflow_client ON "public"."kyc_workflow_history"(client_id);
`;

